draw(graph(lowerhyper,-1.836,2.863),blue);

dot("$(0,0)$", (0,0), NE, fontsize(8));
dot("$(1,0)$", (1,0), NE, fontsize(8));
dot("$(-1,0)$", (-1,0), NW, fontsize(8));
